import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const fresh = async () => (await createHost()) as any;

test('initial state and unknown ids', async () => {
  const h = await fresh();
  for (const n of ['n0', 'n1', 'n2']) assert.deepEqual(await h.node(n), { role: 'follower', term: 0, votedFor: null });
  assert.equal(await h.node('n3'), null);
  assert.equal((await h.timeout('x')).ok, false);
  assert.deepEqual(await h.inFlight(), []);
  await h.__dispose();
});

test('timeout makes a candidate and sends RequestVote', async () => {
  const h = await fresh();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0' });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.from, 'n0');
    assert.equal(m.action, 'RequestVote');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.equal((await h.timeout('n0')).ok, false);
  await h.deliver(msgs[0].id);
  const reply = (await h.inFlight()).find((m: any) => m.action === 'VoteReply');
  assert.deepEqual(reply.data, { term: 1, granted: true });
  assert.equal(reply.to, 'n0');
  await h.deliverAll();
  assert.equal((await h.node('n0'))!.role, 'leader');
  for (const n of ['n1', 'n2']) assert.deepEqual(await h.node(n), { role: 'follower', term: 1, votedFor: 'n0' });
  assert.equal((await h.timeout('n1')).ok, false);
  await h.__dispose();
});

test('competing candidates: at most one leader, each in every order', async () => {
  for (let seed = 0; seed < 30; seed++) {
    const h = await fresh();
    await h.timeout('n0');
    await h.timeout('n1');
    let i = seed;
    for (let msgs = await h.inFlight(); msgs.length; msgs = await h.inFlight()) {
      await h.deliver(msgs[i % msgs.length].id);
      i = (i * 7 + 3) % 101;
    }
    const views = await Promise.all(['n0', 'n1', 'n2'].map((n) => h.node(n)));
    assert.ok(views.filter((v: any) => v.role === 'leader').length <= 1);
    assert.equal(views[0].votedFor, 'n0');
    assert.equal(views[1].votedFor, 'n1');
    await h.__dispose();
  }
});

