test('crash and recover keep term, vote and leader; a down node ignores messages', async () => {
  const h = await fresh();
  assert.equal((await h.recover('n1')).ok, false);
  assert.deepEqual(await h.crash('n1'), { ok: true });
  assert.equal((await h.crash('n1')).ok, false);
  assert.equal((await h.timeout('n1')).ok, false);
  assert.deepEqual(await h.node('n1'), { role: 'down', term: 0, votedFor: null, leader: null });
  await h.timeout('n0');
  await h.deliverAll(); // n1 ignores the request; n2 elects n0
  assert.equal(await h.inFlight().then((m: any[]) => m.length), 0);
  assert.deepEqual(await h.node('n1'), { role: 'down', term: 0, votedFor: null, leader: null });
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.recover('n1'), { ok: true });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 0, votedFor: null, leader: null });
  // the leader crashes and comes back a follower, remembering what it wrote down
  await h.crash('n0');
  assert.deepEqual(await h.node('n0'), { role: 'down', term: 1, votedFor: 'n0', leader: 'n0' });
  await h.recover('n0');
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  // n1 can still start the one election, but n0 and n2 have voted: nobody else leads
  assert.deepEqual(await h.timeout('n1'), { ok: true });
  await h.deliverAll();
  assert.equal((await h.node('n1'))!.role, 'candidate');
  assert.equal((await h.timeout('n0')).ok, false);
  await h.__dispose();
});

