import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const fresh = async () => (await createHost()) as any;

test('initial state and unknown ids', async () => {
  const h = await fresh();
  for (const n of ['n0', 'n1', 'n2']) assert.deepEqual(await h.node(n), { role: 'follower', term: 0, votedFor: null, leader: null });
  assert.equal(await h.node('n3'), null);
  assert.equal((await h.timeout('x')).ok, false);
  assert.deepEqual(await h.inFlight(), []);
  await h.__dispose();
});

test('timeout makes a candidate and sends RequestVote', async () => {
  const h = await fresh();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0', leader: null });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.from, 'n0');
    assert.equal(m.action, 'RequestVote');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.equal((await h.timeout('n0')).ok, false);
  await h.deliver(msgs[0].id);
  const reply = (await h.inFlight()).find((m: any) => m.action === 'VoteReply');
  assert.deepEqual(reply.data, { term: 1, granted: true });
  assert.equal(reply.to, 'n0');
  await h.deliver(reply.id);
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  const announces = (await h.inFlight()).filter((m: any) => m.action === 'Leader');
  assert.deepEqual(announces.map((m: any) => m.to).sort(), ['n1', 'n2']);
  for (const m of announces) assert.deepEqual(m.data, { from: 'n0', term: 1 });
  // n2 may hear Leader before RequestVote: it joins term 1 without voting, then still votes when asked
  await h.deliver(announces.find((m: any) => m.to === 'n2').id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
  await h.deliverAll();
  assert.equal((await h.node('n0'))!.role, 'leader');
  for (const n of ['n1', 'n2']) assert.deepEqual(await h.node(n), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.equal((await h.timeout('n1')).ok, false);
  await h.__dispose();
});

test('giveUp: a candidate follows, keeps its vote, ignores late replies', async () => {
  const h = await fresh();
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.giveUp('zz')).ok, false);
  await h.timeout('n0');
  await h.deliverAll(); // n0 leads
  assert.equal((await h.giveUp('n0')).ok, false); // a leader is not a candidate
  await h.__dispose();

  const g = await fresh();
  await g.timeout('n0');
  assert.deepEqual(await g.giveUp('n0'), { ok: true });
  assert.deepEqual(await g.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.equal((await g.giveUp('n0')).ok, false);
  assert.equal((await g.timeout('n0')).ok, false);
  await g.timeout('n1'); // n1 asks n0, which refuses; n2 decides
  await g.deliverAll();
  const views = await Promise.all(['n0', 'n1', 'n2'].map((n) => g.node(n)));
  assert.equal(views[0].role, 'follower');
  assert.equal(views[0].votedFor, 'n0');
  assert.ok(views.filter((v: any) => v.role === 'leader').length <= 1);
  await g.__dispose();
});

test('competing candidates: at most one leader, each in every order', async () => {
  for (let seed = 0; seed < 30; seed++) {
    const h = await fresh();
    await h.timeout('n0');
    await h.timeout('n1');
    let i = seed;
    for (let msgs = await h.inFlight(); msgs.length; msgs = await h.inFlight()) {
      await h.deliver(msgs[i % msgs.length].id);
      i = (i * 7 + 3) % 101;
    }
    const views = await Promise.all(['n0', 'n1', 'n2'].map((n) => h.node(n)));
    const leaders = views.filter((v: any) => v.role === 'leader');
    assert.equal(leaders.length, 1); // two candidates and one free voter: one always wins
    const id = ['n0', 'n1', 'n2'][views.indexOf(leaders[0])];
    for (const v of views) assert.equal(v.leader, id);
    assert.equal(views.filter((v: any) => v.role === 'candidate').length, 0); // the loser stepped down
    assert.equal(views[0].votedFor, 'n0');
    assert.equal(views[1].votedFor, 'n1');
    await h.__dispose();
  }
});
